"""Quantify installed-release training evidence without inferring missing checkpoints."""
from pathlib import Path
import argparse,collections,hashlib,json
p=argparse.ArgumentParser();p.add_argument('--report',type=Path,required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args()
x=json.loads(a.report.read_text());t={v['table']:v['rows'] for v in x['recentEvidence']}
epoch=max(t['v57_runtime_epoch_r925'],key=lambda r:(int(r['release_code']),int(r['started_at'])))
started=int(epoch['started_at'])
def added(table):return [r for r in t[table] if int(r['created_at'])>=started]
ftrl=[r for r in added('v57_runtime_event_r926') if r['source']=='ResearchAdaptiveLearnerStoreR811' and r['event_type']=='LEARNED' and r['stage']=='LEARNED_EXACTLY_ONCE']
modern=[]
for protocol in t['research_training_protocol_v2']:
 task=next(r for r in t['v57_research_task_r967'] if r['kind']=='TRAIN_CANDIDATE' and r['candidate_id']==protocol['candidate_id'] and r['target_issue']==protocol['registered_issue'] and r['stream_seq']==protocol['protocol_hash'])
 cursor=next((r for r in t['research_training_feature_cursor_cp12'] if r['task_id']==task['task_id']),None)
 modern.append({k:protocol[k] for k in ('candidate_id','model_kind','registered_issue','train_n','validation_n','validation_last')}|{'task_status':task['status'],'last_error':task['last_error'],'feature_next':int(cursor['next_index']) if cursor else 0,'created_during_release':int(protocol['created_at'])>=started})
summary={'scope':'ORIGINAL_REPORT_EVIDENCE_NOT_RECONSTRUCTED_TEST_DB','report_sha256':hashlib.sha256(a.report.read_bytes()).hexdigest(),'release_epoch':epoch,'modern':modern,'modern_feature_total_now':sum(r['feature_next'] for r in modern),'modern_feature_new_during_release_lower_bound':sum(r['feature_next'] for r in modern if r['created_during_release']),'modern_protocols_added':len(added('research_training_protocol_v2')),'modern_development_receipts':len(t['research_development_receipt_v2']),'modern_optimizer_checkpoints':len(t['research_task_checkpoint_v2']),'modern_artifact_identities':len(t['research_artifact_identity_v2']),'legacy_artifacts_total':len(t['r952_artifact']),'legacy_artifacts_added':len(added('r952_artifact')),'legacy_outbox_added':[{k:r[k] for k in ('target_issue','state','created_at')} for r in added('r952_research_outbox')],'legacy_outbox_states':dict(collections.Counter(r['state'] for r in t['r952_research_outbox'])),'legacy_learning_cursor':t['r952_learning_cursor'],'ftrl_exactly_once_added':len(ftrl),'ftrl_target_issues':sorted(r['target_issue'] for r in ftrl),'ftrl_latest_payload':max(ftrl,key=lambda r:int(r['created_at']))['payload_text'] if ftrl else None,'limitations':['REGIME feature cursor is currently3 and was updated after installation; installation-time prefix is not exported, so its exact added row count cannot be inferred.','MAINTENANCE old taskWatermark is a durable review identity, not the model training cutoff.','FTRL, legacy online artifact, and modern development are distinct evidence chains.','Modern development validation is not future calibration or REAL authorization.']}
a.out.parent.mkdir(parents=True,exist_ok=True);a.out.write_text(json.dumps(summary,indent=2)+'\n');print(json.dumps({k:v for k,v in summary.items() if k in ('modern_feature_total_now','modern_feature_new_during_release_lower_bound','modern_protocols_added','legacy_artifacts_added','ftrl_exactly_once_added')},indent=2))
